custom_css:
:root {
  --avatar-base-border-radius: 0px;
  --topBarBlockSize: 50px;
}


* {
  /* filter: none !important; */
}
::-webkit-scrollbar {
  display: none;
}
#clickSlidersTips,
span[name="samplerHelpButton"].note-link-span.fa-circle-question {
  display: none;
  color: transparent;
}
.last_mes .mesAvatarWrapper {
  padding-bottom: 0 !important;
}
#chat {
  border: none;
}
#sheld {
  height: calc(100vh - var(--topBarBlockSize));
  height: calc(100dvh - var(--topBarBlockSize));
  max-height: calc(100dvh - var(--topBarBlockSize));
}
.qr--head {
  display: flex;
  flex-direction: column;
}
#rm_extensions_block .assets-connect-div,
.qr--item {
  display: flex;
  align-items: center !important;
}
.avatar img {
  border: none;
  box-shadow: none;
}
.avatar-container .avatar img,
.recentChat .avatar img,
.hotswap .avatar img {
  box-shadow: 
    2px 3px 5px 0 rgba(203,214,146,0.5);
  border: 3px solid white;
}


#avatar_div_div {
  filter: none;
  margin: 24px 0px 86px;
  padding: 0px !important;
  position: relative;
  background-color: transparent;
  border-radius: 0px;
  display: flex;
  justify-content: flex-end;
}
#avatar_div_div::before {
  content: "MISTY SUN\ASET ORA\ANGE";
  color: #b2bd9b;
  text-shadow: 
    1px 0px 0 white,
    2px 0px 0 white,
    3px 0px 0 white,
    4px 0px 4px rgba(203,214,146,0.5);
  font-size: 24px;
  font-family: "sans-serif";
  font-weight: bold;
  line-height: 1.2;
  letter-spacing: 3px;
  white-space: pre;
  position: absolute;
  top: 28px;
  left: 0px;
  z-index: 45;
}
#avatar_div_div::after {
  content: "Until the very stars burn out and the cosmos collapses into oblivion. Until language exhausts itself and all metaphors wither away.";
  font-size: 12px;
  font-family: "serif";
  font-weight: 380;
  line-height: 1.2;
  letter-spacing: 0px;
  white-space: pre-wrap;
  padding: 0.4em 0em 0.5em 0.6em;
  border-left: 3px solid #c4cfa3;
  color: #9aa673;
  background: linear-gradient(
    to left,
    transparent,
    rgba(255,255,255,0.65)
  );
  width: 80%;
  position: absolute;
  top: 130px;
  left: 0px;
  z-index: 45;
}
#avatar_div_div img {
  transform: rotate(6deg);
  margin-right: 6px;
  border: 1px solid white;
  border-radius: 0px;
  width: 60%;
  height: 120px;
}
.form_create_bottom_buttons_block {
  display: flex;
  justify-content: flex-end;
}
#avatar_div {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 0px;
}
#rm_button_selected_ch h2 {
  font-family: "serif";
  line-height: 1;
  margin-left: 4px;
}


.regex_script_name {
  white-space: normal;
  word-break: break-all;
  line-height: 1.4;
}
.regex-script-label:not(:has(input[type='checkbox']:checked)) {
  background-color: white;
  box-shadow: 
    1px 1px 3px 0px rgba(203,214,146,0.5);
  border-radius: 0px;
}
.regex-script-label {
  background-color: transparent;
  max-width: 85%;
}
.drag-handle.menu-handle {
  position: relative;
  line-height: 1;
}


pre code:not(#qr--modal-messageHolder pre code) {
  color: var(--SmartThemeBodyColor) !important;
  background-color: white !important;
  border-radius: 12px;
  -webkit-box-decoration-break: clone;
  box-shadow: 
    inset -2px -2px 3px 0px #e9f0d1,
    1px 1px 5px 0px #e9f0d1;
  border: none;
}
:not(pre) > code {
  color: var(--SmartThemeQuoteColor);
  background-color: white;
  border-radius: 0px;
  padding: 0em 0.5em;
  border: 2px solid white;
  box-shadow:
    inset 0 -5px 0px 0 #e9f0d1,
    1px 1px 3px 0 rgba(205,213,172,0.5);
}
hr {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-width: 100%;
  max-width: 100%;
  height: 36px;
  max-height: 36px;
  min-height: 36px;
  margin: 0px;
  padding: 0px !important;
  text-align: center;
  white-space: nowrap;
  line-height: 1 !important;
  opacity: 1 !important;
  background: url("https://img.heliar.top/file/1775202559734_组_2.png") center center / contain no-repeat !important;
  color: transparent;
}
.mes_text hr {
  margin-top: -10px !important;
}
blockquote {
  background-color: white !important;
  border-radius: 0px;
  margin: 7px 0px 5px !important;
  padding: 0px 7px 4px !important;
  border: none !important;
  box-shadow: 
    1px 1px 3px 0 rgba(205,213,172,0.75);
  color: var(--SmartThemeEmColor);
  font-style: italic;
}
q {
  border-radius: 50px;
  box-decoration-break: clone;
  background-color: white;
  box-shadow: 
    1px 1px 3px 0px rgba(203,214,146,0.5);
}


#top-bar {
  width: 0px;
  box-shadow: none;
  margin: 0px auto;
}
#top-settings-holder {
  background-color: transparent;
  width: 100dvw;
  margin: 0px auto;
  position: relative;
}
#top-settings-holder::before {
  content: "";
  position: absolute;
  top: 0px;
  width: 100%;
  height: 118px;
  background: url("https://img.heliar.top/file/1775289747178_组_4.png") center center / 100% 100% no-repeat;
  pointer-events: none;
}
#top-settings-holder .drawer-icon {
  position: relative;
  width: 100%;
  font-size: 32px;
  border-radius: 0px;
  color: transparent;
  background: url("https://img.heliar.top/file/1775222884618_组_6.png") center center / contain no-repeat;
  filter: drop-shadow(0px 0px 3px white);
}
#top-settings-holder .drawer-icon.closedIcon {
  opacity: 0;
}
#top-settings-holder .drawer-icon.openIcon {
  opacity: 1;
}


#show_more_messages {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  margin: 20px auto 10px;
  padding: 5px 10px 5px 40px;
  border-radius: 25px;
  font-size: 0px;
  white-space: nowrap;
  color: #B5C1A2;
  background-color: white;
  box-shadow: 
    inset -2px -2px 3px 0px #e9f0d1,
    1px 1px 5px 0px #e9f0d1;
}
#show_more_messages::before {
  content: "•  Last in the rain.";
  line-height: 1;
  font-size: 12px;
  font-weight: bold;
  pointer-events: none;
}
#show_more_messages::after {
  content: "";
  width: 45px;
  height: 45px;
  position: absolute;
  left: -6px;
  top: -13px;
  background: url("https://img.heliar.top/file/1775317131806_色相_饱和度_4.png") center center / contain no-repeat;
}

.mes .mes_block {
  overflow: visible !important;
  margin: 0px 0px;
  padding: 15px 20px 15px 50px;
  border-radius: 0px;
  background-color: transparent;
  width: 100%;
  position: relative;
  z-index: 45 !important;
}
.mes_text {
  padding: 0px 0px;
  margin: 0px;
  position: relative;
}
.mes_text p,
.mes_text content {
  padding: 0px 0px 0px 0em;
  text-align: justify;
  line-break: anywhere;
  text-justify: inter-ideograph;
  word-break: break-all;
  letter-spacing: 0px;
  line-height: 1.6;
}
.mes:not(:has(.mes_reasoning_details[data-type="parsed"])) .mes_text p:first-child {
  margin-top: -0.35em;
}
.mes_text p:last-child {
  margin-bottom: -0.3em;
}

#chat .mes {
  position: relative;
  padding: 0px 0px;
  margin: 178px auto 160px;
  border-radius: 0px 0px 0px 0px;
  border: none;
  align-items: center;
  flex-direction: column;
  width: 100dvw;
  background: url("https://img.heliar.top/file/1775293863940_IMG_20260404_171044.png") center center / 100% auto repeat-y;
}
.mes::before {
  content: "";
  position: absolute;
  top: -178px;
  width: 100%;
  height: 195px;
  background: url("https://img.heliar.top/file/1775294857534_Pride_and_______Prejudice.png") center center / 100% 100% no-repeat;
  pointer-events: none;
  z-index: 12;
}
.mes::after {
  content: "";
  position: absolute;
  bottom: -115px;
  width: 100%;
  height: 115px;
  background: url("https://img.heliar.top/file/1775293680790_图层_73.png") center center / 100% 100% no-repeat;
  pointer-events: none;
  z-index: 45;
}
#chat .last_mes {
  margin-bottom: 250px !important;
}

.mesAvatarWrapper {
  position: absolute;
  top: -178px;
  left: 50%;
  transform: translateX(-50%) !important;
  height: 178px;
  width: 100%;
  border-radius: 0px;
  background-color: transparent;
  margin: 0px auto;
  isolation: isolate;
  z-index: 1;
}
.mes .avatar  {
  position: relative;
  left: 104.5px;
  top: 42px;
  transform: rotate(-6deg);
  border-radius: 0px;
  width: 146px;
  height: 98px;
}
.mes .avatar::before {
  content: "";
  position: absolute;
  left: -76px;
  top: 30px;
  width: 70px;
  height: 62px;
  transform: rotate(6deg);
  background: url("https://img.heliar.top/file/1775162920070_1775162893559.png") center center / cover no-repeat;
  pointer-events: none;
}
.mes .avatar::after {
  content: "";
  position: absolute;
  right: -100px;
  top: 28px;
  width: 89px;
  height: 58px;
  transform: rotate(3deg);
  background: url("https://img.heliar.top/file/1775162920070_1775162893559.png") center center / cover no-repeat;
  pointer-events: none;
}
.mes .avatar img {
  border-radius: inherit;
  width: 100%;
  height: 100%;
}
.mes_timer:empty,
.mes .tokenCounterDisplay:empty {
  display: none;
}
.mes .tokenCounterDisplay,
.mesIDDisplay,
.mes_timer {
  position: absolute;
  line-height: 1;
  opacity: 0 !important;
}
.tokenCounterDisplay {
  top: 0;
  left: 100px;
}
.mes_timer {
  top: 0;
  left: 200px;
}
.mesIDDisplay {
  top: 0;
  left: 300px;
}

.mes .ch_name {
  margin: 0px;
  padding: 0px;
  position: absolute;
  top: 10px;
  display: flex;
  align-items: center;
  line-height: 1;
  white-space: nowrap;
  background-color: transparent;
}
.mes .ch_name .flex-container.flex1 {
  position: relative;
}
.mes .name_text {
  transform: rotate(-6deg);
  position: absolute;
  font-size: 12px;
  top: -52px;
  left: 62px;
  font-family: "serif";
  color: #b2c98c;
}
.mes .timestamp {
  transform: rotate(-6deg);
  position: absolute;
  font-size: 6px;
  top: -162px;
  left: 50px;
}
.mes .timestamp::before {
  content: "@在今天  ";
}
.mes_button {
  opacity: 1;
  filter: none !important;
}
.mes .mes_buttons {
  position: absolute;
  left: 260px;
  top: -58px;
  overflow: visible;
  filter: none !important;
}
.mes_button.mes_edit,
.mes_button.extraMesButtonsHint {
  border-radius: 0;
  filter: none;
  opacity: 1;
  position: relative;
}
.mes_button.mes_edit::before {
  content: "";
  position: absolute;
  top: -9px;
  left: 9px;
  width: 30px;
  height: 30px;
  background: url("https://img.heliar.top/file/1775294380396_图层_71.png") center center / contain no-repeat;
}
.mes_button.extraMesButtonsHint::before {
  content: "";
  position: absolute;
  top: -4px;
  left: -25px;
  width: 35px;
  height: 35px;
  background: url("https://img.heliar.top/file/1775294375040_色相_饱和度_2.png") center center / contain no-repeat;
}
.mes_edit_buttons {
  position: relative;
  left: 35px;
  top: -30px;
  padding: 0;
  filter: none !important;
  opacity: 1 !important;
}
.mes .mes_buttons .extraMesButtons {
  position: relative;
  right: 155px;
  top: 36px;
}
.extraMesButtons>div {
  filter: none !important;
  opacity: 1 !important;
}

.mes_reasoning_details {
  margin: 0px auto 0px;
  min-width: 100% !important;
  max-width: 100%;
}
.mes_reasoning_summary {
  margin: 0px !important;
  display: flex;
  justify-content: flex-end;
}
.mes_reasoning_header_block {
  position: relative;
  height: 0;
  width: 100%;
}
.mes_reasoning_header {
  max-height: 2em;
  min-height: 2em;
  height: 2em;
  width: 50%;
  position: absolute;
  top: -30px;
  left: 164px;
  padding: 0px;
  margin: 0px;
  background: url("https://img.heliar.top/file/1775294132561_图层_74.png") center center / contain no-repeat;
  color: transparent;
  border-radius: 0px;
  box-shadow: none;
  font-size: 15px;
  line-height: 1;
  white-space: nowrap;
  display: flex;
  align-items: center;
  justify-content: center;
}
.mes_reasoning_arrow {
  display: none;
}
#curEditTextarea,
.mes_reasoning,
.mes .reasoning_edit_textarea {
  text-align: justify;
  max-height: 240px;
  margin: 0px 0px;
  padding: 7px 10px;
}
.mes_reasoning {
  border-radius: 10px;
  box-shadow: 
    inset -2px -5px 0px 0 #e9f0d1,
    1px 1px 3px 0 rgba(205,213,172,0.75);
  border: 2px solid white;
  background-color: white;
}

.swipeRightBlock {
  bottom: -40px;
  width: 100%;
  height: 20px;
  z-index: 45;
}
.swipe_left {
  position: absolute;
  left: 25px;
  bottom: -80px;
  opacity: 0 !important;
  border-radius: 0px;
}
.swipe_right {
  position: absolute;
  right: 0px;
  bottom: 0px;
  opacity: 0 !important;
  border-radius: 0px;
}
.swipes-counter,
.mes:not(.last_mes) .swipes-counter {
  position: relative;
  bottom: -74px;
  left: -23px;
  color: var(--SmartThemeQuoteColor);
  line-height: 1.6;
  font-size: 10px;
  white-space: nowrap;
  height: 2em;
  background-color: #f5fbe9;
  box-shadow: 1px 1px 3px 0 rgba(106,125,94,0.5);
  transform: rotate(-3deg);
  visibility: visible !important;
  opacity: 1 !important;
}


#form_sheld {
  position: absolute;
  bottom: 0px;
  margin: 0;
}
#sheld #send_form {
  background-color: transparent !important;
  box-shadow: none;
  border: none;
  border-radius: 0px;
  padding: 0px 0px;
  margin: 0px;
  width: 100%;
  position: relative;
}
#send_form::before {
  content: "";
  position: absolute;
  bottom: 0px;
  width: 100%;
  height: 118px;
  background: url("https://img.heliar.top/file/1775291941157_组_8.png") center center / 100% 100% no-repeat;
  pointer-events: none;
}
#send_form::after {
  content: "";
  position: absolute;
  bottom: 0px;
  width: 100%;
  height: 108px;
  background: url("https://img.heliar.top/file/1775291711444_组_9.png") center center / 100% 100% no-repeat;
  z-index: 45;
  pointer-events: none;
}
#nonQRFormItems {
  position: relative;
  display: flex;
  flex-wrap: wrap;
}
#sheld #send_textarea {
  position: relative;
  top: 2px;
  border: none !important;
  clip-path: none !important;
  resize: none;
  order: 1;
  width: 100%;
  min-width: 100%;
  max-height: 100px;
  min-height: 40px;
  padding: 6px 48px 12px 31px !important;
  margin: 0px 0px 0px 9px;
  border-radius: 0px;
  background-color: white;
}
#leftSendForm {
  padding-left: 0px;
  order: 2;
}
#rightSendForm {
  padding-right: 0px;
  margin-left: auto;
  order: 3;
}
#send_textarea::placeholder {
  opacity: 0;
}
#nonQRFormItems::before {
  content: "在这里打字";
  font-family: "serif";
  font-size: 12px;
  position: absolute;
  top: 5px;
  left: 38px;
  pointer-events: none;
  transition: opacity .15s ease;
  z-index: 45;
}
#nonQRFormItems:has(#send_textarea:focus)::before {
  content: "User was typing......";
  top: 4.5px;
}
#nonQRFormItems:has(#send_textarea[placeholder^="未连接到"])::before {
  content: "未连接到api𖦹𖦹 .ᐟ.ᐟ";
}
#nonQRFormItems:has(#send_textarea:not(:placeholder-shown))::before {
  opacity: 0;
}
#extensionsMenu,
#options {
  background: url("https://img.heliar.top/file/1775194005303_图层_1.png") center center / cover no-repeat;
  border: 3px solid white;
  border-radius: 5px;
  box-shadow: 
    0 0 5px 0 rgba(203,214,146,0.5);
}
#nonQRFormItems [class*="fa-"] {
  opacity: 1 !important;
  filter: none !important;
  color: transparent;
  border-radius: 0px;
  padding: 0;
  width: var(--bottomFormBlockSize);
  height: var(--bottomFormBlockSize);
  font-size: 18px;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 55;
  position: relative;
}
#mes_stop {
  position: relative;
  padding: 0 !important;
  opacity: 1 !important;
  filter: none !important;
}
#options_button {
  top: -3px;
  left: 23px;
}
#extensionsMenuButton {
  top: -3px;
  left: 36px;
}
#mes_stop,
#send_but {
  top: -3px;
  right: 77px;
}
#send_but::before {
  content: "";
  position: absolute;
  top: -12px;
  left: -5px;
  width: 45px;
  height: 45px;
  background: url("https://img.heliar.top/file/1775291427964_组_7.png") center center / contain no-repeat;
}
#mes_stop .fa-circle-stop::before {
  content: "";
  position: absolute;
  top: -12px;
  left: -5px;
  width: 45px;
  height: 45px;
  background: url("https://img.heliar.top/file/1775291435083_组_7_拷贝.png") center center / contain no-repeat;
}
#qr--bar {
  opacity: 1 !important;
  max-height: 33px;
  position: absolute !important;
  top: -38px;
  left: -9999px;
}
#send_form:focus-within #qr--bar {
  left: 0;
}


.drawer-content {
  height: calc(100dvh - var(--topBarBlockSize)) !important;
  min-height: calc(100dvh - var(--topBarBlockSize)) !important;
  max-height: calc(100dvh - var(--topBarBlockSize)) !important;
  background: url("https://img.heliar.top/file/1775194005303_图层_1.png") center center / cover no-repeat;
  padding: 5px 10px 5px !important;
  border-radius: 0px !important;
  border: none !important;
}
.drawer-content:has(.scrollableInner) {
  padding-bottom: 0 !important;
}
#wi-holder {
  margin: 0px;
}
#left-nav-panel .scrollableInner {
  min-height: 100%;
  padding: 0px 0.5em;
}
#right-nav-panel .scrollableInner {
  padding: 0px 0em !important;
}
#form_create {
  padding: 0 6px !important;
}
#persona_connections_list,
.persona_management_left_column,
#world_popup {
  padding: 4px;
}


textarea:not(#vectors_force_chunk_delimiter):not(#send_textarea):not(#qr--modal-message) {
  opacity: 1 !important;
  border-radius: 10px;
  background-color: rgba(250,254,233,0.35);
  border: 2.5px solid rgba(255,255,255,0.65);
  box-shadow: 
    2px 2px 5px 0px rgba(203,214,146,0.35);
  resize: none;
}
input.text_pole,
#vectors_force_chunk_delimiter {
  resize: none;
  border-radius: 4px 12px 12px 12px;
  border: none;
  background-color: white;
  box-shadow: 
    inset -2px -2px 3px 0px #e9f0d1,
    1px 1px 5px 0px #e9f0d1;
}
textarea:focus,
input.text_pole:focus {
  outline: none;
}
#qr--modal-messageHolder {
  margin-top: 20px !important;
}


.popup:not(:has(#load-spinner)),
#character_popup,
#select_chat_popup,
#ti_usage_guide_dialog,
#completion_prompt_manager_popup,
#ti_usage_guide_dialog {
  background: url("https://img.heliar.top/file/1775194005303_图层_1.png") center center / cover no-repeat;
  border-radius: 5px;
  border: 1px solid white;
  box-shadow: 
    inset 0 0 2px 0 white,
    inset 0 0 5px 0 white,
    inset 0 0 10px 0 white,
    0px 3px 0 2px #f2f4e6,
    0px 3px 0px 6px #fff;
  padding: 6px;
}
.popup-content,
.popup-body {
  padding: 3px 3px 10px 3px !important;
}
#select_chat_popup {
  gap: 45px;
}
.select_chat_block {
  background-color: rgba(255,255,255,0.25);
  border-radius: 5px;
}
.secretKeyManagerItem,
.select_chat_block[highlight] {
  border-radius: 0px;
  background-color: white !important;
  border: 3px solid white !important;
  box-shadow: 
    1px 1px 3px 0px #cbd692,
    inset 0px 2px 0px 0px #edf3d9;
}
div[name="selectChatPopupHeader"] {
  position: relative;
  width: 100%;
}
#select_chat_search {
  position: absolute;
  top: 36px;
  width: 100%;
}


body #toast-container {
  width: 100%;
  pointer-events: none;
}
body #toast-container>div {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
