#ti_usage_guide_dialog,
#ui-id-1,
.qr--modal-switcherList,
.flex.flex-1.flex-col.overflow-hidden {
  border: 3px solid white !important;
  border-radius: 5px;
  background: url("https://img.heliar.top/file/1775194005303_图层_1.png") center center / cover no-repeat !important;
  box-shadow: none;
}


#preloader {
  background: url("https://img.heliar.top/file/1775194005303_图层_1.png") center center / cover no-repeat;
}
.popup[open]:has(#load-spinner)::backdrop {
  background: none;
}
#load-spinner {
  transition: none;
  color: transparent;
  top: calc(50% - var(--spinner-size) / 2 - 8px);
  left: calc(50% - var(--spinner-size) / 2 + 7px);
  background: url("https://img.heliar.top/file/1775306800406_图层_75.png") center center / contain no-repeat;
  animation: floatPulse 2.5s ease-in-out infinite;
}
@keyframes floatPulse {
  0%, 100% {
    transform: translateY(0) scale(1);
    opacity: 0.9;
  }
  25% {
    transform: translateY(-12px) scale(1.05);
    opacity: 1;
  }
  50% {
    transform: translateY(5px) scale(0.95);
    opacity: 0.85;
  }
  75% {
    transform: translateY(-8px) scale(1.03);
    opacity: 0.95;
  }
}
